local function BetterQoLXsHoldCover(dt, can)  -- GO: keep the black cover up (layer 1) once its fade out is over
  if BetterQoL.cutin_skip.get(BetterQoL.cutin_skip.COVER) ~= 1 then
    return
  end
  if betterqol_xs.coverT == nil then           -- a later event (new event_menu state): the cover is already up
    betterqol_xs.coverT = BETTERQOL_XS_COVER_OUT_S
  end
  if betterqol_xs.coverT < BETTERQOL_XS_COVER_OUT_S then
    betterqol_xs.coverT = betterqol_xs.coverT + dt
  else
    BetterQoL.cutin_skip.cover(0)
    BetterQoL.cutin_skip.hold()
  end
  if can or betterqol_xs.busy then
    betterqol_xs.stuckT = 0
  else
    betterqol_xs.stuckT = betterqol_xs.stuckT + dt
    if betterqol_xs.stuckT >= BETTERQOL_XS_STUCK_S then
      BetterQoL.cutin_skip.uncover(BetterQoL.cutin_skip.COVER_IN_S, "event not skippable")
    end
  end
end

local function BetterQoLXsKeepBlack()         -- the cover stays black while the flow runs on to the lineups
  if BetterQoL.cutin_skip.get(BetterQoL.cutin_skip.COVER) == 1 then
    BetterQoL.cutin_skip.cover(0)
    BetterQoL.cutin_skip.hold()
  end
end

local function BetterQoLXsJumpUnderCover(dt, can)  -- the fade to black first, then the direct jump (else the cover path)
  BetterQoLXsHoldCover(dt, can)
  if BetterQoL.cutin_skip.get(BetterQoL.cutin_skip.COVER) == 1 and betterqol_xs.coverT < BETTERQOL_XS_COVER_OUT_S then
    return                               -- still fading to black
  end
  if not can then
    return
  end
  local src = "X held (" .. (betterqol_xs.jumpTries or 0) .. ")"
  if BetterQoL.cutin_skip.jump(src) then
    BetterQoLXsJumped(src)
    return
  end
  betterqol_xs.jumpTries = (betterqol_xs.jumpTries or 0) + 1
  if betterqol_xs.jumpTries >= BETTERQOL_XS_JUMP_TRIES then
    betterqol_xs.coverPath = true
    BetterQoL.cutin_skip.log("direct jump not answered: cover path")
    BetterQoLXsSkip("X held (no direct jump)")
  end
end

local function BetterQoLXsStep()
  if BetterQoL.cutin_skip.get(BetterQoL.cutin_skip.ARMED) ~= 1 then
    BetterQoLXsClose()
    betterqol_xs.hold = 0
    return
  end
  local dt = funcLuaCommand(2839043456) or 0
  local can = BetterQoLXsCanSkip()
  if BetterQoL.cutin_skip.get(BetterQoL.cutin_skip.GO) == 1 then
    BetterQoLXsClose()
    if BetterQoL.cutin_skip.get(BetterQoL.cutin_skip.JUMP) == 1 then  -- direct jump: a later pre-match event (if any) is ended the same way
      BetterQoLXsKeepBlack()
      if betterqol_xs.busy then
        if not can then
          betterqol_xs.busy = false
        end
      elseif can then
        if BetterQoL.cutin_skip.jump("next pre-match event") then
          BetterQoLXsJumped("next pre-match event")
        else
          BetterQoLXsSkip("next pre-match event (no jump: retail skip)")
        end
      end
      return
    end
    if not betterqol_xs.coverPath then         -- the jump waits for the fade to black (also in a later event's menu)
      BetterQoLXsJumpUnderCover(dt, can)
      return
    end
    BetterQoLXsHoldCover(dt, can)
    if betterqol_xs.busy then
      betterqol_xs.busyT = betterqol_xs.busyT + dt
      if not can or betterqol_xs.busyT >= BETTERQOL_XS_BUSY_S then
        betterqol_xs.busy = false
      end
    elseif can then
      BetterQoLXsSkip("next pre-match event")
    end
    return
  end
  local holdT = BetterQoLXsHoldTime()
  if holdT <= 0 or not can then
    if betterqol_xs.hold > 0 then
      BetterQoLXsBar(0)
    end
    betterqol_xs.hold = 0
    BetterQoLXsClose()
    return
  end
  if BetterQoLXsHeld() then
    OpenButtonGuideUI()                  -- the retail Y guide too (through the wrapper below, the X guide)
    BetterQoLXsOpen()
    betterqol_xs.hold = betterqol_xs.hold + dt
    BetterQoLXsBar(math.min(1, betterqol_xs.hold / holdT))
    if betterqol_xs.hold >= holdT then
      BetterQoL.cutin_skip.set(BetterQoL.cutin_skip.GO, 1)
      BetterQoL.cutin_skip.set(BetterQoL.cutin_skip.COVER, 1)
      BetterQoL.cutin_skip.cover(BETTERQOL_XS_COVER_OUT_S)   -- the one fade to black; the event is ended once it is black
      betterqol_xs.coverT = 0
      betterqol_xs.stuckT = 0
      betterqol_xs.jumpTries = nil
      betterqol_xs.hold = 0
      BetterQoLXsBar(0)
      BetterQoLXsClose()
      BetterQoL.cutin_skip.log("X held", holdT, "s: fade to black, then the direct jump")
    end
    return
  end
  if betterqol_xs.hold > 0 then
    betterqol_xs.hold = 0
    BetterQoLXsBar(0)
  end
  if betterqol_xs.open then
    betterqol_xs.showT = betterqol_xs.showT - dt
    if betterqol_xs.showT <= 0 then
      BetterQoLXsClose()
    end
  end
end

